93	std::string opensslErrorString() {
94	    unsigned long code = ERR_peek_last_error();
95	    if (code == 0) {
96	        return {};
97	    }
98	    char buffer[256];
99	    ERR_error_string_n(code, buffer, sizeof(buffer));
100	    return buffer;
101	}
