400	// Reads an entire file as raw bytes. The bytes are returned without any
401	// newline/NUL conversion; an empty file yields an empty vector. The path is
402	// never followed through a terminal symlink for the *output*, but key and
403	// input paths are opened normally (a symlink key/input is a legitimate file).
404	bool readAllBytes(const std::string& path, std::vector<unsigned char>& out,
405	                  std::string& error, const char* what) {
406	    int fd = ::open(path.c_str(), O_RDONLY);
407	    if (fd == -1) {
408	        error = std::string("cannot read ") + what + " '" + path + "': " +
409	                errnoDescription(errno);
410	        return false;
411	    }
412	    FdGuard guard(fd);
413	
414	    out.clear();
415	    unsigned char chunk[4096];
416	    for (;;) {
417	        ssize_t got = ::read(fd, chunk, sizeof(chunk));
418	        if (got < 0) {
419	            if (errno == EINTR) {
420	                continue;
421	            }
422	            error = std::string("failed reading ") + what + " '" + path +
423	                    "': " + errnoDescription(errno);
424	            return false;
425	        }
426	        if (got == 0) {
427	            break;  // end of file
428	        }
429	        out.insert(out.end(), chunk, chunk + static_cast<std::size_t>(got));
430	    }
431	    return true;
432	}
433	
434	// Reads exactly kKeyBytes (32) raw bytes from the key file: no trailing data,
435	// no text decoding, no substitute key. A short or long file is an error.
436	bool readKeyFile(const std::string& path, SecureBuffer& key,
437	                 std::string& error) {
438	    int fd = ::open(path.c_str(), O_RDONLY);
439	    if (fd == -1) {
440	        error = "cannot read key file '" + path + "': " +
441	                errnoDescription(errno);
442	        return false;
443	    }
444	    FdGuard guard(fd);
445	
446	    std::size_t total = 0;
447	    while (total < kKeyBytes) {
448	        ssize_t got = ::read(fd, key.data() + total, kKeyBytes - total);
449	        if (got < 0) {
450	            if (errno == EINTR) {
451	                continue;
452	            }
453	            error = "failed reading key file '" + path + "': " +
454	                    errnoDescription(errno);
455	            return false;
456	        }
457	        if (got == 0) {
458	            error = "key file '" + path + "' is " +
459	                    std::to_string(total) + " bytes, expected exactly " +
460	                    std::to_string(kKeyBytes);
461	            return false;
462	        }
463	        total += static_cast<std::size_t>(got);
464	    }
465	
466	    // The file must contain exactly the key, nothing after it.
467	    unsigned char extra;
468	    ssize_t got;
469	    do {
470	        got = ::read(fd, &extra, 1);
471	    } while (got < 0 && errno == EINTR);
472	    if (got < 0) {
473	        error = "failed reading key file '" + path + "': " +
474	                errnoDescription(errno);
475	        return false;
476	    }
477	    if (got > 0) {
478	        error = "key file '" + path + "' is longer than " +
479	                std::to_string(kKeyBytes) +
480	                " bytes; expected exactly 32 raw key bytes";
481	        return false;
482	    }
483	    return true;
484	}
485	
486	// Seals plaintext with AES-256-GCM and builds the complete envelope. The
487	// header (magic/version/algorithm/nonce) is supplied as authenticated data so
488	// the bytes used to interpret the envelope are covered by the tag. On success
489	// envelope holds header || ciphertext || tag; on failure it returns false and
490	// sets error, without ever generating a substitute key.
491	bool sealEnvelope(const unsigned char* key,
492	                  const std::vector<unsigned char>& plaintext,
493	                  std::vector<unsigned char>& envelope,
494	                  std::string& error) {
495	    unsigned char nonce[kNonceBytes];
496	    if (RAND_bytes(nonce, static_cast<int>(kNonceBytes)) != 1) {
497	        error = "secure random source failed";
498	        const std::string detail = opensslErrorString();
499	        if (!detail.empty()) {
500	            error += ": ";
501	            error += detail;
502	        }
503	        OPENSSL_cleanse(nonce, sizeof(nonce));
504	        return false;
505	    }
506	
507	    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
508	    if (ctx == nullptr) {
509	        error = "cannot initialize AES-256-GCM";
510	        OPENSSL_cleanse(nonce, sizeof(nonce));
511	        return false;
512	    }
513	
514	    int outLen = 0;
515	    const std::size_t bodySize = plaintext.size();
516	    envelope.resize(kHeaderBytes + bodySize + kTagBytes);
517	    unsigned char* body = envelope.data() + kHeaderBytes;
518	    unsigned char* tag = body + bodySize;
519	
520	    auto fail = [&](const std::string& message) {
521	        error = message;
522	        EVP_CIPHER_CTX_free(ctx);
523	        OPENSSL_cleanse(nonce, sizeof(nonce));
524	        // Do not leave partial ciphertext in the caller's buffer.
525	        if (!envelope.empty()) {
526	            OPENSSL_cleanse(envelope.data(), envelope.size());
527	        }
528	        envelope.clear();
529	    };
530	
531	    if (EVP_EncryptInit_ex(ctx, EVP_aes_256_gcm(), nullptr, nullptr,
532	                           nullptr) != 1) {
533	        fail("AES-256-GCM initialization failed");
534	        return false;
535	    }
536	    if (EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN,
537	                            static_cast<int>(kNonceBytes), nullptr) != 1) {
538	        fail("cannot set GCM nonce length");
539	        return false;
540	    }
541	    if (EVP_EncryptInit_ex(ctx, nullptr, nullptr, key, nonce) != 1) {
542	        fail("cannot set GCM key and nonce");
543	        return false;
544	    }
545	
546	    // Build the header first and authenticate it before any plaintext byte,
547	    // so magic/version/algorithm/nonce are all bound to the tag. A null output
548	    // marks these bytes as additional authenticated data; OpenSSL reports the
549	    // AAD length back, so use a dedicated counter for ciphertext below rather
550	    // than reusing this one (it would otherwise spoil the empty-input check).
551	    unsigned char* header = envelope.data();
552	    std::memcpy(header, kEnvelopeMagic, kEnvelopeMagicBytes);
553	    header[kEnvelopeMagicBytes] = kEnvelopeVersion;
554	    header[kEnvelopeMagicBytes + 1] = kAlgAes256Gcm;
555	    std::memcpy(header + kEnvelopeMagicBytes + 2, nonce, kNonceBytes);
556	
557	    if (EVP_EncryptUpdate(ctx, nullptr, &outLen, header,
558	                          static_cast<int>(kHeaderBytes)) != 1) {
559	        fail("cannot authenticate envelope header");
560	        return false;
561	    }
562	
563	    int ciphertextLen = 0;
564	    if (!plaintext.empty()) {
565	        if (EVP_EncryptUpdate(ctx, body, &ciphertextLen, plaintext.data(),
566	                              static_cast<int>(plaintext.size())) != 1) {
567	            fail("encryption failed");
568	            return false;
569	        }
570	    }
571	    int finalLen = 0;
572	    if (EVP_EncryptFinal_ex(ctx, body + ciphertextLen, &finalLen) != 1) {
573	        fail("encryption finalization failed");
574	        return false;
575	    }
576	    if (static_cast<std::size_t>(ciphertextLen) +
577	            static_cast<std::size_t>(finalLen) !=
578	        bodySize) {
579	        fail("ciphertext length mismatch");
580	        return false;
581	    }
582	    if (EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG,
583	                            static_cast<int>(kTagBytes), tag) != 1) {
584	        fail("cannot obtain authentication tag");
585	        return false;
586	    }
587	
588	    EVP_CIPHER_CTX_free(ctx);
589	    OPENSSL_cleanse(nonce, sizeof(nonce));
590	    return true;
591	}
