593	// Writes the sealed envelope to a brand new file, rejecting every kind of
594	// existing path (regular file, empty file, directory, symlink including a
595	// dangling one) via O_CREAT|O_EXCL|O_NOFOLLOW. The envelope file is created
596	// readable by the owner (0600) because it is encrypted output; unlike keygen
597	// the 0600 mode is not force-verified here, but group/other never gain access
598	// at creation. A failure after creation closes and removes this run's file,
599	// reporting kCleanupFailed (with a warning) only if that removal fails.
600	EnvelopeSaveResult writeEnvelopeFile(const std::string& path,
601	                                     const std::vector<unsigned char>& bytes) {
602	    EnvelopeSaveResult result;
603	
604	    int fd = ::open(path.c_str(),
605	                    O_WRONLY | O_CREAT | O_EXCL | O_NOFOLLOW,
606	                    S_IRUSR | S_IWUSR);
607	    if (fd == -1) {
608	        const int savedErrno = errno;
609	        result.status = KeySaveStatus::kNotCreated;
610	        if (savedErrno == EEXIST || savedErrno == ELOOP) {
611	            result.error = "refusing to write, path already exists: " + path;
612	        } else {
613	            result.error = "cannot create envelope file '" + path + "': " +
614	                           errnoDescription(savedErrno);
615	        }
616	        return result;
617	    }
618	
619	    FdGuard guard(fd);
620	    result.status = KeySaveStatus::kCleanedUp;
621	    std::string error;
622	
623	    // Envelope output is ciphertext plus a tag; restrict it to owner access.
624	    if (::fchmod(fd, S_IRUSR | S_IWUSR) != 0) {
625	        error = "cannot set envelope file permissions to 0600 on '" + path +
626	                "': " + errnoDescription(errno);
627	    } else {
628	        std::size_t total = 0;
629	        while (total < bytes.size()) {
630	            ssize_t written =
631	                ::write(fd, bytes.data() + total, bytes.size() - total);
632	            if (written < 0) {
633	                if (errno == EINTR) {
634	                    continue;
635	                }
636	                error = "failed writing envelope file '" + path + "': " +
637	                        errnoDescription(errno);
638	                break;
639	            }
640	            if (written == 0) {
641	                error = "failed writing envelope file '" + path +
642	                        "': short write";
643	                break;
644	            }
645	            total += static_cast<std::size_t>(written);
646	        }
647	
648	        if (total == bytes.size()) {
649	            if (::fsync(fd) != 0) {
650	                error = "failed syncing envelope file '" + path + "': " +
651	                        errnoDescription(errno);
652	            } else if (guard.finish() != 0) {
653	                error = "failed closing envelope file '" + path + "': " +
654	                        errnoDescription(errno);
655	            } else {
656	                result.status = KeySaveStatus::kSaved;
657	                result.error.clear();
658	                return result;
659	            }
660	        }
661	    }
662	
663	    guard.close();
664	    if (::unlink(path.c_str()) != 0 && errno != ENOENT) {
665	        result.status = KeySaveStatus::kCleanupFailed;
666	        result.removalWarning =
667	            "could not remove partial envelope file '" + path + "': " +
668	            errnoDescription(errno);
669	    }
670	    result.error = std::move(error);
671	    return result;
672	}
